-- CraftPath :: Solver
-- GENERATED by tools/make_solver.py from ForeverMaster's Lib/Leveling.lua (foreverchanges.pro).
-- Do not edit by hand: change the generator and rebuild. CraftPath's additions over the original:
--   opts.wo, opts.woMult     Working Overtime: extra skill-up chance on yellow and green (added, or multiplied)
--   opts.barter              Bartering: fraction off vendor reagents and vendor recipes
--   opts.chef                Master Chef: extra results per Cooking craft (recovery only)
--   opts.recovery            "keep" | "strict" | "flip": what the things you make are worth back
--   opts.cut, opts.depositRate   auction cut and the deposit lost on what does not sell (fraction of vendor value)
--   opts.vendor, opts.sell, opts.de   prices seen at merchants, vendor sell values, disenchant values by item
--   opts.market { [spell] = copper }  recipes that can be bought on the auction house, used when that is clearly cheaper
--   opts.buyLimited, opts.exclude     allow limited-stock vendor recipes; recipes the player says they cannot get
--   result.net, result.sources, result.how, result.stepInfo, result.econ   receipts
local _, CPath = ...
local FC = {}
CPath.Solver = FC

-- The way from one skill to another in a crafting profession: src/lib/leveling.mjs, the site's calculator, line for line,
-- so the addon's way is the site's to the craft (tests/addon-leveling.test.mjs runs both on the same vectors). Read that
-- file for why each rule is there; here are only what Lua needs: an order kept by hand where JavaScript's Maps and Sets
-- keep insertion order, a stable sort, and no bit operators (Lua 5.1).
--   FC.levelingInput(key)                    the trade's recipes and weights (Data/Leveling.lua), read once
--   FC.levelingSolve(input, opts, yield)     opts: from, to, goal (cheap, fast, profit), side (a, h), owned { spell },
--                                            prices { [itemId] = { copper, listed } }, legacy; yield: called each point
--   FC.levelingOptions(input, opts, base, limit, yield)   the recipes the player could have that would help
--   FC.levelingShopping(steps, recipes, parts, gathered)  what the steps use up, net of what the path makes
--   FC.levelingAsync(work, done)             runs work(yield) a few milliseconds a frame, then done(result)

local CAPS = { 75, 150, 225 }
local SOLD, SKINNED, BOP, UNPRICED = 1, 2, 4, 8
local SELLS = { [0] = 0.5, [1] = 0.9, [2] = 0.8, [3] = 0.35, [4] = 0.5 }
local DUST = 10940
local BOUGHT = { vendor = true, ["one side"] = true }
local SOURCE = { t = "trainer", v = "vendor", r = "reputation", d = "drop", f = "favor", q = "quest" }

local function has(flags, f) return (flags or 0) % (f * 2) >= f end
local function isCap(s) return s == 75 or s == 150 or s == 225 end
local function capBetween(lo, hi) for _, c in ipairs(CAPS) do if c > lo and c < hi then return true end end return false end
local function round(x) return math.floor(x + 0.5) end
local function chance(r, skill)
  if skill < r.yellow then return 1 elseif skill >= r.grey then return 0 end
  return (r.grey - skill) / (r.grey - r.yellow)
end
FC.levelingChance = chance
local function chanceWith(r, skill, wo, mult)
  local p = chance(r, skill)
  if wo and wo > 0 and p > 0 and p < 1 then
    if mult then p = p * (1 + wo) else p = p + wo end
    if p > 1 then p = 1 end
  end
  return p
end
FC.chanceWith = chanceWith

-- A Map that keeps insertion order: keys in order, values by key.
local function ordered() return { keys = {}, vals = {} } end
local function add(m, k, v) if m.vals[k] == nil then m.keys[#m.keys + 1] = k; m.vals[k] = v else m.vals[k] = m.vals[k] + v end end
local function put(m, k, v) if m.vals[k] == nil then m.keys[#m.keys + 1] = k end; m.vals[k] = v end
local function copy(t) local o = {}; for k, v in pairs(t) do o[k] = v end; return o end
local function sortedKeys(t) local ks = {}; for k in pairs(t) do ks[#ks + 1] = k end; table.sort(ks); return ks end
-- Array.prototype.sort is stable: ties keep their order.
local function stableSort(list, less)
  for i, x in ipairs(list) do x.__i = i end
  table.sort(list, function(a, b) if less(a, b) then return true elseif less(b, a) then return false end return a.__i < b.__i end)
  for _, x in ipairs(list) do x.__i = nil end
  return list
end

-- Data/Leveling.lua -----------------------------------------------------------------------------------------------------

local decoded = {}
function FC.levelingInput(key)
  if decoded[key] then return decoded[key] end
  local data = _G.ForeverMasterData
  local raw = data and data.leveling and data.leveling[key]
  if type(raw) ~= "table" then return nil end
  local input = { trade = raw.slug, unit = raw.unit, effort = raw.effort or 0, rods = raw.rods, advice = raw.advice or {}, recipes = {}, items = {} }
  for i, line in ipairs(raw.recipes or {}) do
    local f, n = {}, 0
    for part in (line .. "|"):gmatch("([^|]*)|") do n = n + 1; f[n] = part end
    if n < 13 or not (tonumber(f[1]) and tonumber(f[2]) and tonumber(f[3]) and tonumber(f[4]) and tonumber(f[5]) and f[8] and f[9]) then return nil, "format" end
    local reagents = {}
    for part in f[8]:gmatch("[^,]+") do
      local id, count = part:match("^(%d+):?(%d*)$")
      reagents[#reagents + 1] = { id = tonumber(id), count = tonumber(count) or 1 }
    end
    local src, makes, rod, taught = f[9], tonumber(f[6]), tonumber(f[10]), tonumber(f[13])
    input.recipes[i] = {
      spell = tonumber(f[1]), learn = tonumber(f[2]), yellow = tonumber(f[3]), green = tonumber(f[4]), grey = tonumber(f[5]),
      makes = makes ~= 0 and { id = makes, count = tonumber(f[7]) } or nil, reagents = reagents,
      source = (src:sub(1, 1) == "v" and #src > 1 and src ~= "vl") and "one side" or SOURCE[src:sub(1, 1)],
      side = src == "va" and "a" or src == "vh" and "h" or nil, limited = src == "vl",
      rod = rod ~= 0 and rod or nil, price = tonumber(f[11]) or 0, fee = tonumber(f[12]) or 0, taught_by = taught ~= 0 and taught or nil,
    }
  end
  for id, line in pairs(raw.items or {}) do
    local w, sell, flags, kind = line:match("^([^|]*)|([^|]*)|([^|]*)|([^|]*)$")
    input.items[id] = { w = tonumber(w), sell = tonumber(sell), flags = tonumber(flags), kind = tonumber(kind) }
  end
  input.key = key
  decoded[key] = input
  return input
end

-- Every item a path weighs, as a set.
local ids
function FC.levelingIds()
  if ids then return ids end
  ids = {}
  local data = _G.ForeverMasterData
  local raw = data and data.leveling and data.leveling.ids
  if type(raw) == "string" then for id in raw:gmatch("%d+") do ids[tonumber(id)] = true end end
  return ids
end

-- The shopping list ------------------------------------------------------------------------------------------------------

function FC.levelingShopping(steps, recipes, parts, gathered)
  local need, made, first, maker, more = ordered(), {}, {}, {}, {}
  local skinned = {}
  for _, id in ipairs(gathered or {}) do skinned[id] = true end
  -- Object.values() of the parts (by item id), then of the recipes (by spell): numeric keys go up.
  for _, set in ipairs({ parts or {}, recipes }) do
    for _, k in ipairs(sortedKeys(set)) do local r = set[k]; if r.makes and not skinned[r.makes.id] then maker[r.makes.id] = r end end
  end
  for i, s in ipairs(steps) do
    local r = recipes[s.spell]
    for _, x in ipairs(r.reagents) do add(need, x.id, x.count * s.crafts); if first[x.id] == nil then first[x.id] = i end end
    if r.makes then made[r.makes.id] = (made[r.makes.id] or 0) + r.makes.count * s.crafts end
  end
  for _ = 1, 4 do
    local snap = {}
    for _, id in ipairs(need.keys) do snap[#snap + 1] = { id, need.vals[id] } end
    for _, e in ipairs(snap) do
      local id, n = e[1], e[2]
      local r, short = maker[id], n - (made[id] or 0)
      if r and short > 0 then
        local crafts = math.ceil(short / r.makes.count)
        made[id] = (made[id] or 0) + crafts * r.makes.count
        more[id] = (more[id] or 0) + crafts * r.makes.count
        for _, x in ipairs(r.reagents) do add(need, x.id, x.count * crafts); if first[x.id] == nil then first[x.id] = first[id] end end
      end
    end
  end
  local buy, mine = {}, {}
  for _, id in ipairs(need.keys) do
    local n, m = need.vals[id], made[id] or 0
    if n > m then buy[#buy + 1] = { id = id, count = n - m } end
    if m ~= 0 then mine[#mine + 1] = { id = id, count = math.min(n, m) } end
  end
  local byFirst = function(a, b) return first[a.id] < first[b.id] end
  return { buy = stableSort(buy, byFirst), made = stableSort(mine, byFirst), more = more }
end

-- The solver -------------------------------------------------------------------------------------------------------------

function FC.levelingSolve(input, opts, yield)
  opts = opts or {}
  local from, to, goal, side, legacy = opts.from or 1, opts.to or 300, opts.goal or "cheap", opts.side, opts.legacy and true or false
  local wo, woMult = opts.wo or 0, opts.woMult and true or false
  local function chance(r, skill) return chanceWith(r, skill, wo, woMult) end
  local barter = opts.barter or 0
  local chef = (input.trade == "cooking") and (opts.chef or 0) or 0
  local recovery = opts.recovery or (goal == "profit" and "flip" or "keep")
  local cut, depositRate = opts.cut or 0.05, opts.depositRate or 0
  local vendorSeen, sellSeen, realDe = opts.vendor or {}, opts.sell or {}, opts.de or {}
  local deValue = (opts.chooseDe == false) and {} or realDe   -- the route can be picked blind to disenchanting, then costed with it
  local market, buyLimited, exclude = opts.market or {}, opts.buyLimited and true or false, opts.exclude or {}
  local hurdle = true   -- while the route is picked, an auction-house recipe must beat its price by a margin; the report uses the real price
  local owned = {}
  for _, s in ipairs(opts.owned or {}) do owned[s] = true end
  local prices, items = opts.prices, input.items
  local dust = input.unit == "dust" and prices and prices[DUST] and prices[DUST][1] or nil
  local copper = input.unit ~= "dust" or dust ~= nil
  local choose = opts.choose or recovery
  local sells = choose ~= "keep" and copper
  local reports = recovery ~= "keep" and copper
  local function ahOf(id) return prices and prices[id] and prices[id][1] or nil end
  local function vend(id)
    local it = items[id]
    local v = vendorSeen[id]
    if v == nil and it and has(it.flags, SOLD) and input.unit ~= "dust" then v = it.w end
    if v == nil then return nil end
    return v * (1 - barter)
  end
  local function weight(id)
    local it, ah = items[id], ahOf(id)
    local v = vend(id)
    if input.unit == "dust" then
      if dust == nil then return it and it.w or 20 end
      if ah and v then return math.min(ah, v) end
      return ah or v or (it and it.w or 20) * dust
    end
    if ah == nil then return v or (it and it.w or 100) end
    if v then return math.min(ah, v) end
    return ah
  end
  local function sourceOf(id)
    local ah, v = ahOf(id), vend(id)
    if v and (not ah or v <= ah) then return "vendor" end
    if ah then return "ah" end
    return "guess"
  end
  local effort
  if input.unit == "dust" and dust == nil then effort = 0
  elseif input.effort ~= 0 then effort = input.effort
  else effort = input.unit == "dust" and 50 or 0 end
  local function shopOk(r) return (r.source == "vendor" and (not r.limited or buyLimited)) or (r.source == "one side" and r.side == side) end
  local function usableBy(r)
    if owned[r.spell] then return true end
    if legacy then return r.source == "trainer" or r.source == "vendor" end
    if exclude[r.spell] then return false end
    return r.source == "trainer" or shopOk(r) or market[r.spell] ~= nil
  end
  -- What getting the recipe costs, and where from: its vendor, or the auction house when that is cheaper or the only way.
  local function recipeCost(r)
    local c, via
    if BOUGHT[r.source] and (legacy or shopOk(r)) then c, via = (r.price or 0) * (1 - barter), "vendor" end
    local m = market[r.spell]
    if m then
      local mm = hurdle and (m * 1.2 + 5000) or m
      if c == nil or mm < c then c, via = mm, "ah" end
    end
    return c or 0, via
  end
  local meta = {}
  local all, usable, byId = {}, {}, {}
  for i, r in ipairs(input.recipes) do
    local cost = 0
    for _, x in ipairs(r.reagents) do cost = cost + weight(x.id) * x.count end
    meta[r] = meta[r] or { __index = r }
    local c = setmetatable({ cost = cost }, meta[r])
    all[i] = c
    if usableBy(r) then usable[#usable + 1] = c; if byId[r.spell] == nil then byId[r.spell] = c end end
  end
  local rods = input.rods or {}
  local rodItem = {}
  for _, item in pairs(rods) do rodItem[item] = true end
  local rodCache = {}
  local function rodRecipe(cat)
    if rodCache[cat] == nil then
      rodCache[cat] = false
      for _, r in ipairs(usable) do if r.makes and r.makes.id == rods[cat] then rodCache[cat] = r; break end end
    end
    return rodCache[cat] or nil
  end
  local usedAsReagent = {}
  for _, o in ipairs(usable) do for _, x in ipairs(o.reagents) do usedAsReagent[x.id] = true end end
  local inter = {}
  for _, r in ipairs(usable) do if r.makes and not rodItem[r.makes.id] and usedAsReagent[r.makes.id] then inter[r.makes.id] = true end end
  local rodsHeld = {}
  for cat in pairs(rods) do local r = rodRecipe(cat); if r and r.learn < from then rodsHeld[cat] = true end end
  local listed = {}
  if prices then for id, p in pairs(prices) do listed[id] = p[2] end end
  local function unitSale(id, depth)
    local it = items[id]
    local sell = sellSeen[id] or (it and it.sell) or 0
    local best, how = sell, "vendor"
    if recovery == "flip" then
      local ah = ahOf(id)
      if ah and ah > 0 and not (it and has(it.flags, BOP)) and (((depth and depth[id]) or 0) > 0) then
        local s = SELLS[it and it.kind or 0] or 0.5
        local v = s * (1 - cut) * ah + (1 - s) * sell - (1 - s) * depositRate * sell
        if v > best then best, how = v, "ah" end
      end
    end
    local de = deValue[id]
    if de and de > best then best, how = de, "de" end
    return best, how
  end
  local function sale(r, depth)
    if not r.makes then return 0 end
    local each = unitSale(r.makes.id, depth)
    return each * r.makes.count * (1 + chef)
  end
  local function longer(r, b) return r.yellow > b.yellow and not (r.makes and inter[r.makes.id]) and not (b.makes and inter[b.makes.id]) end

  local function walk(budget, skip)
    local held, steps, left, depth, scores = copy(rodsHeld), {}, copy(budget.vals), copy(listed), {}
    local skill = from
    while skill < to do
      local best
      local last = steps[#steps]
      for _, r in ipairs(usable) do
        if not (r.learn > skill or skip[r.spell]) then
          local p = chance(r, skill)
          if p ~= 0 then
            local extra, ok = 0, true
            if r.rod and not held[r.rod] then
              local rod = rodRecipe(r.rod)
              if not rod or rod.learn > skill then ok = false else extra = rod.cost / 20 end
            end
            if ok then
              local mid = r.makes and r.makes.id
              local free = mid ~= nil and left[mid] ~= nil and left[mid] > 0
              local cost
              if free then cost = math.max(0, r.cost - weight(mid) * r.makes.count) else cost = r.cost + extra + effort end
              if sells and not free and not (mid ~= nil and left[mid] ~= nil) then cost = cost - sale(r, depth) end
              local perPoint
              if sells then perPoint = cost / p elseif cost > 0 then perPoint = cost / p else perPoint = -p end
              local key = goal == "fast" and 1 / p or 0
              local rank = ((last and r.spell == last.spell) and 0 or 2) + (r.source == "trainer" and 0 or 1)
              local cmp
              if not best then cmp = -1
              elseif key < best.key - 1e-9 then cmp = -1
              elseif key > best.key + 1e-9 then cmp = 1
              elseif perPoint < best.perPoint - 1e-9 then cmp = -1
              elseif perPoint < best.perPoint + 1e-9 then cmp = 0
              else cmp = 1 end
              if cmp < 0 or (cmp == 0 and (rank < best.rank or (rank == best.rank and longer(r, best.r)))) then
                best = { r = r, perPoint = perPoint, p = p, rank = rank, key = key }
              end
            end
          end
        end
      end
      for _, r in ipairs(usable) do
        local a = input.advice[r.spell]
        if a and a <= skill and not skip[r.spell] and chance(r, skill) >= (best and best.p or 1) then
          best = { r = r, p = chance(r, skill), perPoint = best and best.perPoint, key = best and best.key }
          break
        end
      end
      if not best then break end
      local r, p = best.r, best.p
      if goal == "fast" then scores[skill] = best.key else scores[skill] = best.perPoint end
      local mid = r.makes and r.makes.id
      if mid ~= nil and left[mid] ~= nil then left[mid] = left[mid] - r.makes.count / p
      elseif sells and mid ~= nil and depth[mid] ~= nil then depth[mid] = depth[mid] - r.makes.count / p end
      if r.rod and not held[r.rod] then held[r.rod] = true; steps[#steps + 1] = { from = skill, to = skill, spell = rodRecipe(r.rod).spell, crafts = 1, rod = true } end
      last = steps[#steps]
      if last and last.spell == r.spell and not last.rod and not isCap(skill) then last.to = skill + 1; last.expected = last.expected + 1 / p
      else steps[#steps + 1] = { from = skill, to = skill + 1, spell = r.spell, expected = 1 / p } end
      skill = skill + 1
      if yield then yield() end
    end
    steps.scores = scores
    return steps
  end
  local function uses(steps)
    local n = ordered()
    for _, s in ipairs(steps) do
      if not s.rod then for _, x in ipairs(byId[s.spell].reagents) do if inter[x.id] then add(n, x.id, x.count * s.expected) end end end
    end
    return n
  end
  local function plan(skip)
    local budget = ordered()
    local steps = walk(budget, skip)
    local seen = {}
    while true do
      local u, nextB, parts = uses(steps), ordered(), {}
      for _, id in ipairs(u.keys) do put(nextB, id, math.ceil(u.vals[id])); parts[#parts + 1] = id .. "=" .. tostring(nextB.vals[id]) end
      local key = table.concat(parts, ",")
      local same = #nextB.keys == #budget.keys
      if same then for _, id in ipairs(nextB.keys) do if budget.vals[id] ~= nextB.vals[id] then same = false; break end end end
      if same then break end
      if seen[key] then
        local b2 = ordered()
        for _, id in ipairs(nextB.keys) do put(b2, id, math.max(nextB.vals[id], budget.vals[id] or 0)) end
        budget = b2; steps = walk(budget, skip)
        break
      end
      seen[key] = true; budget = nextB; steps = walk(budget, skip)
    end
    return budget, steps
  end
  local function once(steps)
    if legacy then return 0 end
    local n, seen = 0, {}
    for _, s in ipairs(steps) do
      if not seen[s.spell] then
        seen[s.spell] = true
        local r = byId[s.spell]
        if not owned[s.spell] then n = n + (r.fee or 0) + recipeCost(r) end
      end
    end
    return n
  end
  local function total(steps)
    local n, made, depth = 0, {}, copy(listed)
    for _, s in ipairs(steps) do
      local r = byId[s.spell]
      local crafts = s.rod and 1 or s.expected
      n = n + crafts * (r.cost + effort)
      local mid = r.makes and r.makes.id
      if mid ~= nil and inter[mid] then made[mid] = (made[mid] or 0) + crafts * r.makes.count
      elseif sells and mid ~= nil and not s.rod then
        local k = 0
        while k < crafts do
          local f = math.min(1, crafts - k)
          n = n - f * sale(r, depth)
          depth[mid] = (depth[mid] or 0) - f * r.makes.count
          k = k + 1
        end
      end
    end
    local u = uses(steps)
    for _, id in ipairs(u.keys) do n = n - math.min(u.vals[id], made[id] or 0) * weight(id) end
    return n + once(steps)
  end
  local function crafts(steps) local n = 0; for _, s in ipairs(steps) do n = n + (s.rod and 1 or s.expected) end; return n end
  local worse, same
  if goal == "fast" then
    worse = function(now, was) return crafts(now) > crafts(was) + 1e-6 or (crafts(now) > crafts(was) - 1e-6 and total(now) > total(was) + 1e-6) end
    same = function(now, was) return crafts(now) > crafts(was) - 1e-6 and total(now) > total(was) - 1e-6 end
  else
    worse = function(now, was) return total(now) > total(was) + 1e-6 end
    same = function(now, was) return total(now) > total(was) - 1e-6 end
  end
  local function formulas(steps)
    local out, seen = {}, {}
    for _, s in ipairs(steps) do
      if not s.rod and not owned[s.spell] and not seen[s.spell] then
        local src = byId[s.spell].source
        if (legacy and src == "vendor") or (not legacy and (BOUGHT[src] or market[s.spell] ~= nil)) then seen[s.spell] = true; out[#out + 1] = s.spell end
      end
    end
    return out
  end
  local skip = {}
  local budget, steps = plan(skip)
  local changed = true
  while changed do
    changed = false
    for _, spell in ipairs(formulas(steps)) do
      local trySkip = copy(skip); trySkip[spell] = true
      local tb, ts = plan(trySkip)
      local reach = legacy and to or (steps[#steps] and steps[#steps].to or to)
      local lastTo = ts[#ts] and ts[#ts].to
      if not ((lastTo ~= nil and lastTo < reach) or worse(ts, steps) or (same(ts, steps) and #formulas(ts) >= #formulas(steps))) then
        skip[spell] = true; budget, steps = tb, ts; changed = true
        break
      end
    end
  end
  local scores = steps.scores
  local function pointsCost(r, a, b)
    local n = 0
    for k = a, b - 1 do local c = chance(r, k); if c == 0 then return nil end; n = n + 1 / c end
    return n
  end
  changed = true
  while changed do
    changed = false
    for i = 1, #steps do
      local st = steps[i]
      if not (st.rod or st.to - st.from > 3) then
        for _, j in ipairs({ i - 1, i + 1 }) do
          local other = steps[j]
          if other and not other.rod then
            local r = byId[other.spell]
            local lo, hi = math.min(st.from, other.from), math.max(st.to, other.to)
            if not (r.learn > lo or capBetween(lo, hi)) then
              local extra = pointsCost(r, st.from, st.to)
              if not (extra == nil or extra * (r.cost + effort) > 1.3 * st.expected * (byId[st.spell].cost + effort)) then
                other.from, other.to, other.expected = lo, hi, other.expected + extra
                table.remove(steps, i); changed = true
                break
              end
            end
          end
        end
      end
      if changed then break end
    end
  end
  local function feeds(s) local m = byId[s.spell].makes; return m ~= nil and budget.vals[m.id] ~= nil end
  local function stepCost(r, a, b) local n = pointsCost(r, a, b); if n == nil then return nil end; return n * (r.cost + effort) end
  local i = 1
  while i + 2 <= #steps do
    local a, b, c = steps[i], steps[i + 1], steps[i + 2]
    local merged = false
    if not (a.spell ~= c.spell or a.rod or b.rod or c.rod or feeds(a) or feeds(b) or capBetween(a.from, c.to)) then
      local A, B = byId[a.spell], byId[b.spell]
      local now = b.expected * (B.cost + effort) + c.expected * (A.cost + effort)
      local keepA = nil
      if A.learn <= b.from then keepA = stepCost(A, b.from, b.to) end
      local keepB = stepCost(B, c.from, c.to)
      local best1 = keepA ~= nil and keepA + c.expected * (A.cost + effort) or nil
      local best2 = keepB ~= nil and b.expected * (B.cost + effort) + keepB or nil
      local pick
      if best1 ~= nil and (best2 == nil or best1 <= best2) then pick = 1 elseif best2 ~= nil then pick = 2 end
      local chosen = pick == 1 and best1 or best2
      if pick and not (chosen > 1.3 * now) then
        if pick == 1 then a.to = c.to; a.expected = a.expected + (pointsCost(A, b.from, b.to) + c.expected); table.remove(steps, i + 1); table.remove(steps, i + 1)
        else b.to = c.to; b.expected = b.expected + pointsCost(B, c.from, c.to); table.remove(steps, i + 2) end
        merged = true
      end
    end
    if merged then i = math.max(1, i - 1) else i = i + 1 end
  end
  i = 2
  while i <= #steps do
    local s, p = steps[i], steps[i - 1]
    if not s.rod and not p.rod and s.spell == p.spell and not isCap(s.from) then p.to = s.to; p.expected = p.expected + s.expected; table.remove(steps, i)
    else i = i + 1 end
  end
  local out = {}
  for k, s in ipairs(steps) do
    local keep = false
    local m = byId[s.spell].makes
    if not s.rod and m then
      for j = k + 1, #steps do
        local o = steps[j]
        if not o.rod then for _, x in ipairs(byId[o.spell].reagents) do if x.id == m.id then keep = true; break end end end
        if keep then break end
      end
    end
    out[k] = { from = s.from, to = s.to, spell = s.spell, crafts = s.rod and 1 or math.ceil(s.expected), rod = s.rod or nil, keep = keep or nil }
  end

  local used, usedList, usedMakes = {}, {}, {}
  for _, s in ipairs(out) do if not used[s.spell] then used[s.spell] = true; usedList[#usedList + 1] = s.spell end end
  for _, sp in ipairs(usedList) do local m = byId[sp].makes; if m then usedMakes[m.id] = true end end
  local reagentIds, seenId = {}, {}
  for _, sp in ipairs(usedList) do for _, x in ipairs(byId[sp].reagents) do if not seenId[x.id] then seenId[x.id] = true; reagentIds[#reagentIds + 1] = x.id end end end
  local shopping = ordered()
  for _, s in ipairs(out) do for _, x in ipairs(byId[s.spell].reagents) do add(shopping, x.id, x.count * s.crafts) end end
  local recipes = {}
  for _, sp in ipairs(usedList) do
    local r = byId[sp]
    recipes[sp] = { name = r.name, learn = r.learn, yellow = r.yellow, green = r.green, grey = r.grey, source = r.source, taught_by = r.taught_by, makes = r.makes, reagents = r.reagents, rod = r.rod }
  end
  local parts = {}
  for _, id in ipairs(reagentIds) do
    if not (items[id] and has(items[id].flags, SKINNED)) then
      local maker
      for _, r in ipairs(usable) do if r.makes and r.makes.id == id and not used[r.spell] then maker = r; break end end
      if maker and not usedMakes[maker.makes.id] then parts[id] = { name = maker.name, makes = maker.makes, reagents = maker.reagents, spell = maker.spell } end
    end
  end
  local gathered, sold = {}, {}
  for _, id in ipairs(reagentIds) do
    if items[id] and has(items[id].flags, SKINNED) then gathered[#gathered + 1] = id end
    if items[id] and has(items[id].flags, SOLD) then sold[#sold + 1] = id end
  end
  table.sort(gathered); table.sort(sold)
  local shop = {}
  for _, id in ipairs(shopping.keys) do shop[#shop + 1] = { id = id, count = shopping.vals[id] } end
  stableSort(shop, function(a, b) return weight(b.id) * b.count < weight(a.id) * a.count end)
  local file = { steps = out, recipes = recipes, parts = parts, gathered = gathered, sold = sold, shopping = shop, rods = input.rods }
  if legacy then return file end

  deValue, hurdle = realDe, false
  local list = FC.levelingShopping(out, recipes, parts, gathered)
  local price, priceIds = {}, {}
  local function priceOf(id) if not priceIds[id] then priceIds[id] = true; price[id] = copper and round(weight(id)) or nil end end
  for _, x in ipairs(list.buy) do priceOf(x.id) end
  for _, x in ipairs(list.made) do priceOf(x.id) end
  for _, s in ipairs(out) do local m = byId[s.spell].makes; if m then priceOf(m.id) end end
  local spent = nil
  if copper then spent = 0; for _, x in ipairs(list.buy) do spent = spent + x.count * weight(x.id) end end
  local depth, resale, resaleAll = copy(listed), 0, 0
  for _, s in ipairs(out) do
    local r = byId[s.spell]
    if not (s.rod or s.keep or not r.makes) then
      local mid, it = r.makes.id, items[r.makes.id]
      resaleAll = resaleAll + s.crafts * r.makes.count * math.max(it and it.sell or 0, (it and has(it.flags, BOP)) and 0 or 0.95 * (ahOf(mid) or 0))
      for _ = 1, s.crafts do resale = resale + sale(r, depth); depth[mid] = (depth[mid] or 0) - r.makes.count end
    end
  end
  local each = {}
  if sells then
    for _, s in ipairs(out) do
      local m = byId[s.spell].makes
      if not s.rod and not s.keep and m and each[m.id] == nil then each[m.id] = round(unitSale(m.id, copy(listed))) end
    end
  end
  local short = {}
  if prices then for _, x in ipairs(list.buy) do if listed[x.id] ~= nil and listed[x.id] < x.count then short[x.id] = listed[x.id] end end end
  local oneTime = once(steps)
  local purchases = {}
  for _, sp in ipairs(usedList) do
    local r = byId[sp]
    local recipePrice, via = recipeCost(r)
    if not owned[sp] and (recipePrice ~= 0 or (r.fee or 0) ~= 0) then
      purchases[#purchases + 1] = { spell = sp, price = round(recipePrice), fee = r.fee or 0, via = via, limited = r.limited }
    end
  end
  local priced = 0
  if prices then for _, x in ipairs(list.buy) do if prices[x.id] then priced = priced + 1 end end end
  local others = {}
  for _, r in ipairs(all) do if not usableBy(r) then others[r.spell] = r.cost + effort - (sells and sale(r, copy(listed)) or 0) end end
  local n = 0
  for _, s in ipairs(out) do n = n + s.crafts end
  file.list, file.price, file.short, file.sells, file.purchases = list, price, short, each, purchases
  file["end"] = out[#out] and out[#out].to or from
  file.scores, file.others = scores, others
  file.totals = { crafts = n, spent = spent and round(spent + oneTime) or nil, oneTime = oneTime, resale = copper and round(resale) or nil, resaleAll = copper and round(resaleAll) or nil, priced = priced, reagents = #list.buy }
  -- CraftPath receipts ----------------------------------------------------------------------------------------------
  local sources, how = {}, {}
  for id in pairs(priceIds) do sources[id] = sourceOf(id) end
  for _, s in ipairs(out) do
    local m = byId[s.spell].makes
    if m and how[m.id] == nil then local _, h = unitSale(m.id, listed); how[m.id] = h end
  end
  file.sources, file.how, file.recovery, file.unit = sources, how, recovery, input.unit
  file.net = spent and (round(spent + oneTime) - (reports and round(resale) or 0)) or nil
  file.stepInfo = {}
  for k, s in ipairs(out) do
    local r = byId[s.spell]
    local p = chance(r, s.from)
    local saleEach = (reports and not s.keep and not s.rod and r.makes) and sale(r, listed) or 0
    local best
    for _, o in ipairs(usable) do
      if o.spell ~= s.spell and o.learn <= s.from then
        local po = chance(o, s.from)
        if po > 0 then
          local c = (o.cost + effort - (reports and sale(o, listed) or 0)) / po
          if not best or c < best.perPoint then
            -- what it would cost, once, to be able to make it at all (nothing if the route already uses it)
            local once = (owned[o.spell] or used[o.spell]) and 0 or ((o.fee or 0) + recipeCost(o))
            best = { spell = o.spell, perPoint = c, p = po, makes = o.makes, once = once }
          end
        end
      end
    end
    file.stepInfo[k] = { cost = r.cost, sale = saleEach, p = p, perPoint = p > 0 and (r.cost + effort - saleEach) / p or nil, alt = best,
      source = r.source, makes = r.makes, reagents = r.reagents }
    if yield then yield() end
  end
  -- Every recipe's cost and what its result is worth back, for the opportunities list. mode overrides the recovery mode.
  file.econ = function(skill, mode)
    local saved = recovery
    recovery = mode or recovery
    local rows = {}
    for _, r in ipairs(all) do
      if r.makes then
        local each, h = unitSale(r.makes.id, listed)
        local back = each * r.makes.count * (1 + chef)
        rows[#rows + 1] = { spell = r.spell, cost = r.cost, sale = back, how = h, profit = back - r.cost, usable = usableBy(r) and true or false,
          p = chance(r, skill or from), learn = r.learn, makes = r.makes, source = r.source, reagents = r.reagents }
      end
    end
    recovery = saved
    return rows
  end
  return file
end

function FC.levelingOptions(input, opts, base, limit, yield)
  limit = limit or 8
  local from, to, goal, side = opts.from or 1, opts.to or 300, opts.goal or "cheap", opts.side
  local function chance(r, skill) return chanceWith(r, skill, opts.wo or 0, opts.woMult) end
  local sellsBack = (opts.recovery and opts.recovery ~= "keep") or (not opts.recovery and goal == "profit")
  local owned = {}
  for _, s in ipairs(opts.owned or {}) do owned[s] = true end
  local function usable(r)
    if owned[r.spell] or r.source == "trainer" then return true end
    if opts.exclude and opts.exclude[r.spell] then return false end
    return (r.source == "vendor" and (not r.limited or opts.buyLimited)) or (r.source == "one side" and r.side == side) or (opts.market ~= nil and opts.market[r.spell] ~= nil)
  end
  local function score(s)
    if goal == "fast" then return s.totals.crafts end
    if s.totals.spent == nil then return nil end
    return s.totals.spent - (sellsBack and (s.totals.resale or 0) or 0)
  end
  local function beats(r, k, v)
    local p = chance(r, k)
    if p == 0 then return false end
    if goal == "fast" then return 1 / p < v - 1e-9 end
    local c = base.others[r.spell]
    return c ~= nil and v > 0 and c / p < 0.99 * v
  end
  local function guessed(r)
    for _, x in ipairs(r.reagents) do
      local it = input.items[x.id]
      if it and has(it.flags, UNPRICED) and not (opts.prices and opts.prices[x.id]) then return true end
    end
    return false
  end
  local candidates = {}
  for _, r in ipairs(input.recipes) do
    if not usable(r) and not guessed(r) and r.learn < to and r.grey > from then
      local any = false
      for k, v in pairs(base.scores) do if k >= r.learn and beats(r, k, v) then any = true; break end end
      if any then candidates[#candidates + 1] = r end
    end
  end
  local out = {}
  for _, r in ipairs(candidates) do
    if yield then yield() end
    local mine = {}
    for _, s in ipairs(opts.owned or {}) do mine[#mine + 1] = s end
    mine[#mine + 1] = r.spell
    local trialOpts = copy(opts); trialOpts.owned = mine
    local trial = FC.levelingSolve(input, trialOpts, yield)
    local uses = false
    for _, s in ipairs(trial.steps) do if s.spell == r.spell then uses = true; break end end
    if uses and trial["end"] >= base["end"] then
      local sb, st = score(base), score(trial)
      local gold = (sb ~= nil and st ~= nil) and sb - st or nil
      local crafts = base.totals.crafts - trial.totals.crafts
      local enough
      if goal == "fast" then enough = crafts >= math.max(3, 0.02 * base.totals.crafts)
      else enough = base.totals.spent ~= nil and gold ~= nil and gold >= math.max(10000, 0.02 * math.abs(sb)) end
      if enough then
        out[#out + 1] = { spell = r.spell, source = r.source, side = r.side, limited = r.limited, taught_by = r.taught_by, learn = r.learn, name = r.name, makes = r.makes,
          gold = base.totals.spent ~= nil and gold ~= nil and round(gold) or nil, crafts = crafts }
      end
    end
  end
  if goal == "fast" then
    stableSort(out, function(a, b) if a.crafts ~= b.crafts then return a.crafts > b.crafts end return (a.gold or 0) > (b.gold or 0) end)
  else
    stableSort(out, function(a, b) if a.gold ~= b.gold then return a.gold > b.gold end return a.crafts > b.crafts end)
  end
  for k = #out, limit + 1, -1 do out[k] = nil end
  return out
end

-- Runs work(yield) a few milliseconds a frame: the solver yields at each skill point, so the game never stalls.
local clock = debugprofilestop or function() return os.clock() * 1000 end
function FC.levelingAsync(work, done, budgetMs)
  local co = coroutine.create(function() return work(coroutine.yield) end)
  local function step()
    local start = clock()
    while true do
      local ok, result = coroutine.resume(co)
      if not ok then done(nil, result); return end
      if coroutine.status(co) == "dead" then done(result); return end
      if clock() - start > (budgetMs or 6) then break end
    end
    if C_Timer and C_Timer.After then C_Timer.After(0, step) else step() end
  end
  step()
end

-- CraftPath: the route for a recovery mode, never worse than the routes picked for the stricter modes sold the same way.
-- The walk is greedy, so a route chosen for what its results sell for can cost more than the plain cheapest route
-- once both are sold; this solves each and keeps the lowest net. Likewise it is never worse than the route
-- that buys no recipes off the auction house or from limited-stock vendors, unless that route stops short.
function FC.solveBest(input, opts, yield)
  local best = FC.levelingSolve(input, opts, yield)
  local mode = opts.recovery or "keep"
  if best.net == nil then return best end
  local tries = {}
  if mode == "flip" then tries = { { "strict" }, { "keep" } } elseif mode == "strict" then tries = { { "keep" } } end
  if mode ~= "keep" and opts.de and next(opts.de) then
    tries[#tries + 1] = { mode, false }
    if mode == "flip" then tries[#tries + 1] = { "strict", false } end
  end
  for _, t in ipairs(tries) do
    local o = copy(opts); o.choose = t[1]
    if t[2] == false then o.chooseDe = false end
    local r = FC.levelingSolve(input, o, yield)
    if r.net ~= nil and r["end"] >= best["end"] and r.net < best.net then best = r end
  end
  if (opts.market and next(opts.market)) or opts.buyLimited then
    local o = copy(opts); o.market, o.buyLimited = nil, nil
    local r = FC.solveBest(input, o, yield)
    if r.net ~= nil and r["end"] >= best["end"] and r.net < best.net then best = r end
  end
  return best
end
